import { useVendorProductsQuery } from '../../store/api/vendorApi';
export default function VendorProducts(){const{data,isLoading}=useVendorProductsQuery();const products=data?.products||[];return <main className="mx-auto max-w-7xl px-4 py-10"><h1 className="font-heading text-5xl text-navy">Vendor Products</h1><div className="card mt-6 overflow-x-auto p-5"><button className="btn-gold mb-4">Add Product</button>{isLoading?<p>Loading...</p>:!products.length?<p>No products listed.</p>:<table className="w-full text-left"><thead><tr className="text-navy"><th>Image</th><th>Name</th><th>Stock</th><th>Price</th><th>Active</th><th>Actions</th></tr></thead><tbody>{products.map(p=><tr className="border-t" key={p._id}><td><img src={p.thumbnail||'/logo.png'} className="h-12 w-12 object-contain"/></td><td>{p.name}</td><td><span className="rounded bg-gold/20 px-2 py-1">{p.stock}</span></td><td>₹{p.salePrice}</td><td><input type="checkbox" defaultChecked={p.isActive}/></td><td><button className="text-navy">Edit</button> / <button className="text-red-600">Delete</button></td></tr>)}</tbody></table>}</div><div className="card mt-6 grid gap-3 p-5"><h2 className="font-heading text-3xl text-navy">Add/Edit Modal Form</h2><input className="input" placeholder="Name"/><textarea className="input" placeholder="Description"/><input className="input" type="file" multiple/><div className="grid gap-3 md:grid-cols-4"><input className="input" placeholder="Price"/><input className="input" placeholder="Sale price"/><input className="input" placeholder="Cost price"/><input className="input" placeholder="Stock"/></div><button className="btn-gold">Save Product</button></div></main>}
